1	#include "q1_0.h"
2	
3	#include <assert.h>
4	#include <math.h>
5	#include <string.h>
6	
7	#define GGML_CPU_FP16_TO_FP32(x) lab_fp16_to_fp32(x)
8	#define NOINLINE __attribute__((noinline))
9	#define UNUSED(x) (void)(x)
10	
11	// ---- exact fp16 <-> fp32, copied from ggml/src/ggml-impl.h ----------------
12	
13	static inline float fp32_from_bits(uint32_t w) {
14	    float f;
15	    memcpy(&f, &w, sizeof(f));
16	    return f;
17	}
18	
19	static inline uint32_t fp32_to_bits(float f) {
20	    uint32_t w;
21	    memcpy(&w, &f, sizeof(w));
22	    return w;
23	}
24	
25	float lab_fp16_to_fp32(uint16_t h) {
26	    const uint32_t w = (uint32_t) h << 16;
27	    const uint32_t sign = w & UINT32_C(0x80000000);
28	    const uint32_t two_w = w + w;
29	
30	    const uint32_t exp_offset = UINT32_C(0xE0) << 23;
31	    const float exp_scale = 0x1.0p-112f;
32	    const float normalized_value = fp32_from_bits((two_w >> 4) + exp_offset) * exp_scale;
33	
34	    const uint32_t magic_mask = UINT32_C(126) << 23;
35	    const float magic_bias = 0.5f;
36	    const float denormalized_value = fp32_from_bits((two_w >> 17) | magic_mask) - magic_bias;
37	
38	    const uint32_t denormalized_cutoff = UINT32_C(1) << 27;
39	    const uint32_t result = sign |
40	        (two_w < denormalized_cutoff ? fp32_to_bits(denormalized_value) : fp32_to_bits(normalized_value));
41	    return fp32_from_bits(result);
42	}
43	
44	uint16_t lab_fp32_to_fp16(float f) {
45	    const float scale_to_inf  = 0x1.0p+112f;
46	    const float scale_to_zero = 0x1.0p-110f;
47	    float base = (fabsf(f) * scale_to_inf) * scale_to_zero;
48	
49	    const uint32_t w = fp32_to_bits(f);
50	    const uint32_t shl1_w = w + w;
51	    const uint32_t sign = w & UINT32_C(0x80000000);
52	    uint32_t bias = shl1_w & UINT32_C(0xFF000000);
53	    if (bias < UINT32_C(0x71000000)) {
54	        bias = UINT32_C(0x71000000);
55	    }
56	
57	    base = fp32_from_bits((bias >> 1) + UINT32_C(0x07800000)) + base;
58	    const uint32_t bits = fp32_to_bits(base);
59	    const uint32_t exp_bits = (bits >> 13) & UINT32_C(0x00007C00);
60	    const uint32_t mantissa_bits = bits & UINT32_C(0x00000FFF);
61	    const uint32_t nonsign = exp_bits + mantissa_bits;
62	    return (sign >> 16) | (shl1_w > UINT32_C(0xFF000000) ? UINT16_C(0x7E00) : nonsign);
63	}
64	
65	// ---- scalar reference, copied from ggml/src/ggml-cpu/quants.c:127 ---------
66	
67	void ggml_vec_dot_q1_0_q8_0_generic(int n, float * GGML_RESTRICT s, size_t bs, const void * GGML_RESTRICT vx, size_t bx, const void * GGML_RESTRICT vy, size_t by, int nrc) {
68	    const int qk = QK1_0;
69	    const int nb = n / qk;
70	
71	    assert(n % qk == 0);
72	    assert(nrc == 1);
73	    UNUSED(nrc);
74	    UNUSED(bx);
75	    UNUSED(by);
76	    UNUSED(bs);
77	
78	    const block_q1_0 * GGML_RESTRICT x = vx;
79	    const block_q8_0 * GGML_RESTRICT y = vy;
80	
81	    float sumf = 0.0;
82	
83	    for (int i = 0; i < nb; i++) {
84	        const float d0 = GGML_CPU_FP16_TO_FP32(x[i].d);
85	
86	        float sumi = 0.0f;
87	
88	        for (int k = 0; k < 4; k++) {
89	            const block_q8_0 * GGML_RESTRICT yb = &y[i * 4 + k];
90	            const float d1 = GGML_CPU_FP16_TO_FP32(yb->d);
91	            int sumi_block = 0;
92	
93	            const uint8_t * GGML_RESTRICT bits = &x[i].qs[k * 4];
94	            const int8_t  * GGML_RESTRICT qy   = yb->qs;
95	
96	            for (int b = 0; b < 4; ++b, qy += 8) {
97	                const unsigned mask = bits[b];
98	                sumi_block += ((mask & 0x01) ? qy[0] : -qy[0])
99	                           +  ((mask & 0x02) ? qy[1] : -qy[1])
100	                           +  ((mask & 0x04) ? qy[2] : -qy[2])
101	                           +  ((mask & 0x08) ? qy[3] : -qy[3])
102	                           +  ((mask & 0x10) ? qy[4] : -qy[4])
103	                           +  ((mask & 0x20) ? qy[5] : -qy[5])
104	                           +  ((mask & 0x40) ? qy[6] : -qy[6])
105	                           +  ((mask & 0x80) ? qy[7] : -qy[7]);
106	            }
107	
108	            sumi += d1 * sumi_block;
109	        }
110	
111	        sumf += d0 * sumi;
112	    }
113	
114	    *s = sumf;
115	}
116	
117	// ---- F4a: row-parallel repack + scalar reference gemv ---------------------
118	
119	void repack_q1_0_to_q1_0_64x1(const block_q1_0 * GGML_RESTRICT src,
120	                              block_q1_0_64x1 * GGML_RESTRICT dst, int nr, int n) {
121	    const int nb = n / QK1_0;
122	    assert(nr % Q1_NX1_N == 0);
123	    assert(n % QK1_0 == 0);
124	
125	    memset(dst, 0, (size_t)(nr / Q1_NX1_N) * nb * sizeof(block_q1_0_64x1));
126	
127	    for (int r = 0; r < nr; ++r) {
128	        const int g = r / Q1_NX1_N;   // brick group
129	        const int j = r % Q1_NX1_N;   // lane inside the brick
130	        for (int ib = 0; ib < nb; ++ib) {
131	            const block_q1_0 * b = &src[(size_t)r * nb + ib];
132	            block_q1_0_64x1 * o  = &dst[(size_t)g * nb + ib];
133	            o->d[j] = b->d;
134	            for (int c = 0; c < QK1_0; ++c) {
135	                const uint8_t bit = (b->qs[c / 8] >> (c % 8)) & 1;
136	                o->qs[c][j / 8] = (uint8_t)((o->qs[c][j / 8] & ~(1u << (j % 8))) | (bit << (j % 8)));
137	            }
138	        }
139	    }
140	}
141	
142	// Keeps the exact float-op order of ggml_vec_dot_q1_0_q8_0_generic per row,
143	// so results are bit-exact vs running that on the original row-major data.
144	void gemv_q1_0_64x1_q8_0_generic(int n, float * GGML_RESTRICT s, const void * GGML_RESTRICT vx, const void * GGML_RESTRICT vy, int nr) {
145	    const int nb = n / QK1_0;
146	    assert(n % QK1_0 == 0);
147	    assert(nr % Q1_NX1_N == 0);
148	
149	    const block_q1_0_64x1 * GGML_RESTRICT bricks = vx;
150	    const block_q8_0      * GGML_RESTRICT y      = vy;
151	
152	    for (int g = 0; g < nr / Q1_NX1_N; ++g) {
153	        const block_q1_0_64x1 * GGML_RESTRICT bx = bricks + (size_t)g * nb;
154	        for (int j = 0; j < Q1_NX1_N; ++j) {
155	            float sumf = 0.0f;
156	            for (int ib = 0; ib < nb; ++ib) {
157	                const float d0 = GGML_CPU_FP16_TO_FP32(bx[ib].d[j]);
158	                float sumi = 0.0f;
159	                for (int k = 0; k < 4; ++k) {
160	                    const block_q8_0 * GGML_RESTRICT yb = &y[ib * 4 + k];
161	                    const float d1 = GGML_CPU_FP16_TO_FP32(yb->d);
162	                    int sumi_block = 0;
163	                    for (int c = 0; c < QK8_0; ++c) {
164	                        const int bit = (bx[ib].qs[k * QK8_0 + c][j / 8] >> (j % 8)) & 1;
165	                        sumi_block += bit ? yb->qs[c] : -yb->qs[c];
166	                    }
