1	// Correctness harness for the Q1_0 x Q8_0 vec_dot kernels.
2	//
3	// Two gates per case:
4	// - bit-exact vs the scalar reference, for kernels that do the same float ops
5	//   in the same order (generic, vl256, vl128). Build uses -ffp-contract=off
6	//   so neither side gets FMA-fused.
7	// - normalized error vs a double-precision reference < NORM_ERR_MAX, for
8	//   kernels that reorder the float accumulation (none today; this is the
9	//   gate the F4 row-parallel repack kernels will be judged by).
10	//
11	// Data domain matches ggml: q8 quants are in [-127,127] (ggml Q8_0 never
12	// emits -128; vneg on int8 -128 wraps and would falsely diverge from the
13	// scalar reference, which negates in 32-bit).
14	//
15	// --inject: flips one weight bit after taking a baseline and requires the
16	// dispatcher result to change. Proves the harness can detect a broken kernel.
17	//
18	// This harness is correctness-only. Speed is measured on vsim/FPGA (rdcycle,
19	// see vsim-demo/q1_0) - QEMU timing is misleading by design.
20	
21	#include "q1_0.h"
22	
23	#include <math.h>
24	#include <stdio.h>
25	#include <stdlib.h>
26	#include <string.h>
27	
28	#if defined(__riscv_v_intrinsic)
29	#include <riscv_vector.h>
30	#endif
31	
32	#define NORM_ERR_MAX 1e-4
33	
34	static uint64_t rng_state = 0x243F6A8885A308D3ull;
35	
36	static uint64_t rng_next(void) {
37	    rng_state ^= rng_state << 13;
38	    rng_state ^= rng_state >> 7;
39	    rng_state ^= rng_state << 17;
40	    return rng_state;
41	}
42	
43	static uint16_t rand_fp16(float lo, float hi) {
44	    const float v = lo + (hi - lo) * ((rng_next() >> 11) * 0x1.0p-53f);
45	    return lab_fp32_to_fp16(v);
46	}
47	
48	static void fill_random(block_q1_0 * x, int nbx, block_q8_0 * y, int nby) {
49	    for (int i = 0; i < nbx; ++i) {
50	        x[i].d = rand_fp16(-2.0f, 2.0f);
51	        for (int j = 0; j < QK1_0 / 8; ++j) {
52	            x[i].qs[j] = (uint8_t)rng_next();
53	        }
54	    }
55	    for (int i = 0; i < nby; ++i) {
56	        y[i].d = rand_fp16(0.001f, 1.0f);
57	        for (int j = 0; j < QK8_0; ++j) {
58	            y[i].qs[j] = (int8_t)((int)(rng_next() % 255) - 127); // [-127,127]
59	        }
60	    }
61	}
62	
63	// reference dot in double, plus sum of |terms| for error normalization
64	static double ref_dot_double(const block_q1_0 * x, const block_q8_0 * y, int n, double * sum_abs) {
65	    double sum = 0.0, sabs = 0.0;
66	    for (int i = 0; i < n / QK1_0; ++i) {
67	        const double d0 = (double)lab_fp16_to_fp32(x[i].d);
68	        for (int k = 0; k < 4; ++k) {
69	            const block_q8_0 * yb = &y[i * 4 + k];
70	            const double d1 = (double)lab_fp16_to_fp32(yb->d);
71	            long sumi = 0;
72	            for (int j = 0; j < QK8_0; ++j) {
73	                const int bit = (x[i].qs[k * 4 + j / 8] >> (j % 8)) & 1;
74	                sumi += bit ? yb->qs[j] : -yb->qs[j];
75	            }
76	            sum  += d0 * d1 * (double)sumi;
77	            sabs += fabs(d0 * d1 * (double)sumi);
78	        }
79	    }
80	    *sum_abs = sabs;
81	    return sum;
82	}
83	
84	static uint32_t f32_bits(float f) {
85	    uint32_t w;
86	    memcpy(&w, &f, sizeof(w));
87	    return w;
88	}
89	
90	// ---- kernels under test ----------------------------------------------------
91	
92	typedef void (*vec_dot8_t)(int, float *, size_t, const void *, size_t, const void *, size_t, int);
93	
94	#if defined(__riscv_v_intrinsic)
95	static void vl256_as8(int n, float * s, size_t bs, const void * vx, size_t bx, const void * vy, size_t by, int nrc) {
96	    (void)bs; (void)bx; (void)by; (void)nrc;
97	    ggml_vec_dot_q1_0_q8_0_vl256(n, s, vx, vy);
98	}
99	static void vl128_as8(int n, float * s, size_t bs, const void * vx, size_t bx, const void * vy, size_t by, int nrc) {
100	    (void)bs; (void)bx; (void)by; (void)nrc;
101	    ggml_vec_dot_q1_0_q8_0_vl128(n, s, vx, vy);
102	}
103	#endif
104	
105	struct kernel_ent {
106	    const char * name;
107	    vec_dot8_t   fn;
108	    int          bitexact;   // 1: must match scalar reference bit-for-bit
109	    size_t       min_vlen;   // runtime VLEN (bits) required, 0 = always
110	    int          is_dispatcher;
111	};
112	
113	static struct kernel_ent kernels[8];
114	static int n_kernels = 0;
115	
116	static size_t runtime_vlen(void) {
117	#if defined(__riscv_v_intrinsic)
118	    return __riscv_vlenb() * 8;
119	#else
120	    return 0;
121	#endif
122	}
123	
124	static void init_kernels(void) {
125	    // every path does the same float ops in the same order as the scalar
126	    // reference, so the dispatcher is bit-exact at every VLEN
127	    kernels[n_kernels++] = (struct kernel_ent){"dispatch", ggml_vec_dot_q1_0_q8_0, 1, 0, 1};
128	#if defined(__riscv_v_intrinsic)
129	    kernels[n_kernels++] = (struct kernel_ent){"vl256", vl256_as8, 1, 256, 0};
130	    kernels[n_kernels++] = (struct kernel_ent){"vl128", vl128_as8, 1, 128, 0};
131	#endif
132	}
133	
134	// ---- correctness -----------------------------------------------------------
135	
136	static int run_case(const block_q1_0 * x, const block_q8_0 * y, int n,
137	                    const char * name, double * max_norm_err, uint32_t * checksum) {
138	    float ref = INFINITY;
139	    ggml_vec_dot_q1_0_q8_0_generic(n, &ref, 0, x, 0, y, 0, 1);
140	
141	    double sum_abs = 0.0;
142	    const double dref = ref_dot_double(x, y, n, &sum_abs);
143	    const double norm = sum_abs > 1e-30 ? sum_abs : 1e-30;
144	
145	    const size_t vlen = runtime_vlen();
146	    int failed = 0;
147	
148	    for (int ki = 0; ki < n_kernels; ++ki) {
149	        const struct kernel_ent * k = &kernels[ki];
150	        if (vlen < k->min_vlen) {
151	            continue;
152	        }
153	        float got = INFINITY;
154	        k->fn(n, &got, 0, x, 0, y, 0, 1);
155	        if (k->is_dispatcher) {
156	            *checksum ^= f32_bits(got);
157	        }
158	
159	        if (k->bitexact && f32_bits(ref) != f32_bits(got)) {
160	            printf("FAIL %-8s %-12s n=%5d bit-exact: ref=%.9g (0x%08x) got=%.9g (0x%08x)\n",
161	                   k->name, name, n, (double)ref, f32_bits(ref), (double)got, f32_bits(got));
162	            failed = 1;
163	        }
164	        const double norm_err = fabs((double)got - dref) / norm;
165	        if (norm_err > *max_norm_err) {
166	            *max_norm_err = norm_err;
167	        }
168	        if (norm_err > NORM_ERR_MAX) {
169	            printf("FAIL %-8s %-12s n=%5d norm_err=%.3g vs double ref %.9g (got %.9g)\n",
170	                   k->name, name, n, norm_err, dref, (double)got);
171	            failed = 1;
172	        }
173	    }
174	    return failed;
175	}
176	
177	static int test_size(int n, int trials, uint32_t * checksum) {
178	    const int nbx = n / QK1_0;
179	    const int nby = n / QK8_0;
180	    block_q1_0 * x = malloc((size_t)nbx * sizeof(block_q1_0));
181	    block_q8_0 * y = malloc((size_t)nby * sizeof(block_q8_0));
182	
183	    int failed = 0;
184	    double max_norm_err = 0.0;
185	
186	    for (int t = 0; t < trials; ++t) {
187	        fill_random(x, nbx, y, nby);
188	        failed += run_case(x, y, n, "random", &max_norm_err, checksum);
189	    }
190	
191	    // edge cases
192	    fill_random(x, nbx, y, nby);
193	    for (int i = 0; i < nbx; ++i) memset(x[i].qs, 0x00, QK1_0 / 8);
194	    failed += run_case(x, y, n, "bits=0x00", &max_norm_err, checksum);
195	
196	    for (int i = 0; i < nbx; ++i) memset(x[i].qs, 0xFF, QK1_0 / 8);
197	    failed += run_case(x, y, n, "bits=0xFF", &max_norm_err, checksum);
198	
199	    fill_random(x, nbx, y, nby);
200	    for (int i = 0; i < nby; ++i) memset(y[i].qs, 127, QK8_0);
201	    failed += run_case(x, y, n, "q8=+127", &max_norm_err, checksum);
202	
203	    for (int i = 0; i < nby; ++i) memset(y[i].qs, -127, QK8_0);
204	    failed += run_case(x, y, n, "q8=-127", &max_norm_err, checksum);
205	
206	    fill_random(x, nbx, y, nby);
207	    for (int i = 0; i < nbx; ++i) x[i].d = 0;
208	    failed += run_case(x, y, n, "d0=0", &max_norm_err, checksum);
209	
210	    printf("n=%5d: %3d cases x %d kernels, %s, max_norm_err=%.3g\n",
211	           n, trials + 5, n_kernels, failed ? "FAIL" : "ok", max_norm_err);
212	    free(x);
213	    free(y);
214	    return failed;
215	}
216	
217	// ---- F4a/F4b: row-parallel repack + gemv -----------------------------------
218	//
219	// Gate 1 (F4a, bit-exact): repack + gemv_..._generic must reproduce, bit for
220	// bit, what the per-row scalar vec_dot computes on the original row-major
221	// weights (the scalar gemv keeps the reference float-op order).
222	// Gate 2 (F4b, double-ref): the RVV gemv fuses mul+add (vfmacc), so per output
223	// row: |got - double_ref| / sum|terms| < NORM_ERR_MAX.
224	
225	typedef void (*gemv_t)(int, float *, const void *, const void *, int);
226	
227	struct gemv_ent {
228	    const char * name;
229	    gemv_t       fn;
230	    int          bitexact;   // 1: must equal the per-row vec_dot reference bit-for-bit
231	    size_t       min_vlen;
232	};
233	
234	static struct gemv_ent gemv_kernels[4];
235	static int n_gemv = 0;
236	
237	static void init_gemv_kernels(void) {
238	    const size_t vlen = runtime_vlen();
239	    gemv_kernels[n_gemv++] = (struct gemv_ent){"gemv_ref",  gemv_q1_0_64x1_q8_0_generic, 1, 0};
240	    // dispatcher routes to the reordering RVV kernels once VLEN >= 512
241	    gemv_kernels[n_gemv++] = (struct gemv_ent){"gemv_dsp",  gemv_q1_0_64x1_q8_0, vlen < 512, 0};
242	#if defined(__riscv_v_intrinsic)
243	    gemv_kernels[n_gemv++] = (struct gemv_ent){"gemv_512",  gemv_q1_0_64x1_q8_0_vl512,  0, 512};
244	    gemv_kernels[n_gemv++] = (struct gemv_ent){"gemv_1024", gemv_q1_0_64x1_q8_0_vl1024, 0, 1024};
245	#endif
246	}
247	
248	static int run_gemv_case(const block_q1_0 * x, const block_q8_0 * y, int n, int nr,
249	                         const char * name, double * max_norm_err) {
250	    const int nb = n / QK1_0;
251	    const size_t vlen = runtime_vlen();
252	    int failed = 0;
253	    int nprint = 0;
254	
255	    // per-row references on the ORIGINAL row-major data
256	    float  * expect = malloc((size_t)nr * sizeof(float));
257	    double * dref   = malloc((size_t)nr * sizeof(double));
258	    double * norm   = malloc((size_t)nr * sizeof(double));
259	    for (int r = 0; r < nr; ++r) {
260	        ggml_vec_dot_q1_0_q8_0_generic(n, &expect[r], 0, x + (size_t)r * nb, 0, y, 0, 1);
261	        double sabs = 0.0;
262	        dref[r] = ref_dot_double(x + (size_t)r * nb, y, n, &sabs);
263	        norm[r] = sabs > 1e-30 ? sabs : 1e-30;
264	    }
265	
266	    block_q1_0_64x1 * bricks = malloc((size_t)(nr / Q1_NX1_N) * nb * sizeof(block_q1_0_64x1));
267	    repack_q1_0_to_q1_0_64x1(x, bricks, nr, n);
268	
269	    float * got = malloc((size_t)nr * sizeof(float));
270	    for (int ki = 0; ki < n_gemv; ++ki) {
271	        const struct gemv_ent * k = &gemv_kernels[ki];
272	        if (vlen < k->min_vlen) {
273	            continue;
274	        }
275	        memset(got, 0xAA, (size_t)nr * sizeof(float));
276	        k->fn(n, got, bricks, y, nr);
277	
278	        for (int r = 0; r < nr; ++r) {
279	            if (k->bitexact && f32_bits(expect[r]) != f32_bits(got[r])) {
280	                if (nprint++ < 5) {
281	                    printf("FAIL %-9s %-10s n=%5d nr=%3d row=%3d bit-exact: ref=%.9g (0x%08x) got=%.9g (0x%08x)\n",
282	                           k->name, name, n, nr, r, (double)expect[r], f32_bits(expect[r]), (double)got[r], f32_bits(got[r]));
283	                }
284	                failed = 1;
285	            }
286	            const double norm_err = fabs((double)got[r] - dref[r]) / norm[r];
287	            if (norm_err > *max_norm_err) {
288	                *max_norm_err = norm_err;
289	            }
290	            if (norm_err > NORM_ERR_MAX) {
291	                if (nprint++ < 5) {
292	                    printf("FAIL %-9s %-10s n=%5d nr=%3d row=%3d norm_err=%.3g vs double ref %.9g (got %.9g)\n",
293	                           k->name, name, n, nr, r, norm_err, dref[r], (double)got[r]);
294	                }
295	                failed = 1;
296	            }
297	        }
298	    }
299	
300	    free(expect); free(dref); free(norm); free(bricks); free(got);
301	    return failed;
302	}
303	
304	static int test_repack_gemv(void) {
305	    static const struct { int n, nr; } shapes[] = {
306	        {128, 64}, {512, 128}, {1024, 64}, {256, 192},
307	    };
308	    const int trials = 10;
309	    int failed = 0;
310	    double max_norm_err = 0.0;
311	
312	    for (size_t si = 0; si < sizeof(shapes) / sizeof(shapes[0]); ++si) {
313	        const int n = shapes[si].n, nr = shapes[si].nr;
314	        const int nbx = nr * (n / QK1_0);
315	        const int nby = n / QK8_0;
316	        block_q1_0 * x = malloc((size_t)nbx * sizeof(block_q1_0));
317	        block_q8_0 * y = malloc((size_t)nby * sizeof(block_q8_0));
318	
319	        int sf = 0;
320	        for (int t = 0; t < trials; ++t) {
321	            fill_random(x, nbx, y, nby);
322	            sf += run_gemv_case(x, y, n, nr, "random", &max_norm_err);
323	        }
324	        // edges: all-plus / all-minus sign planes
325	        fill_random(x, nbx, y, nby);
326	        for (int i = 0; i < nbx; ++i) memset(x[i].qs, 0x00, QK1_0 / 8);
327	        sf += run_gemv_case(x, y, n, nr, "bits=0x00", &max_norm_err);
328	        for (int i = 0; i < nbx; ++i) memset(x[i].qs, 0xFF, QK1_0 / 8);
329	        sf += run_gemv_case(x, y, n, nr, "bits=0xFF", &max_norm_err);
330	
331	        printf("gemv n=%5d nr=%3d: %3d cases x %d kernels, %s, max_norm_err=%.3g\n",
332	               n, nr, trials + 2, n_gemv, sf ? "FAIL" : "ok", max_norm_err);
333	        failed += sf;
334	        free(x);
335	        free(y);
336	    }
337	    return failed;
338	}
339	
340	// prove the harness detects a wrong kernel: flip one weight bit, result must change
341	static int test_inject(void) {
342	    const int n = 512;
343	    block_q1_0 x[512 / QK1_0];
344	    block_q8_0 y[512 / QK8_0];
345	    fill_random(x, 512 / QK1_0, y, 512 / QK8_0);
346	
347	    // make the target element's contribution unmissable
348	    x[1].d = lab_fp32_to_fp16(1.0f);
349	    y[1 * 4 + 2].d = lab_fp32_to_fp16(1.0f);
350	    y[1 * 4 + 2].qs[13] = 100;
351	
352	    float base = 0, after = 0;
353	    ggml_vec_dot_q1_0_q8_0(n, &base, 0, x, 0, y, 0, 1);
354	
355	    x[1].qs[2 * 4 + 13 / 8] ^= (uint8_t)(1u << (13 % 8)); // flip sign bit of element 13, group 2, block 1
356	    ggml_vec_dot_q1_0_q8_0(n, &after, 0, x, 0, y, 0, 1);
357	
358	    if (f32_bits(base) == f32_bits(after)) {
359	        printf("INJECT FAIL: flipped weight bit not detected (result unchanged: %.9g)\n", (double)base);
360	        return 1;
361	    }
362	    printf("INJECT ok: flipped weight bit changed result %.9g -> %.9g (delta ~ %g, expect ~200)\n",
363	           (double)base, (double)after, (double)after - (double)base);
364	    return 0;
365	}
366	
367	int main(int argc, char ** argv) {
368	    // canary values for the fp16 conversion this harness depends on
369	    if (lab_fp16_to_fp32(0x3C00) != 1.0f || lab_fp16_to_fp32(0xC000) != -2.0f ||
370	        lab_fp16_to_fp32(0x7BFF) != 65504.0f || lab_fp32_to_fp16(1.0f) != 0x3C00 ||
371	        lab_fp32_to_fp16(-2.0f) != 0xC000) {
372	        printf("FAIL: fp16 conversion self-test\n");
373	        return 1;
374	    }
375	
376	    init_kernels();
377	    init_gemv_kernels();
378	
379	#if defined(__riscv_v_intrinsic)
380	    const size_t vlen_bits = runtime_vlen();
381	    const char * path = vlen_bits >= 256 ? "vl256" : vlen_bits >= 128 ? "vl128" : "generic";
382	    printf("build: RVV, VLEN=%zu bits -> dispatcher path: %s\n", vlen_bits, path);
383	#else
384	    printf("build: scalar (dispatcher == generic reference)\n");
385	#endif
386	
387	    if (argc > 1 && strcmp(argv[1], "--inject") == 0) {
388	        return test_inject();
389	    }
390	
391	    const int sizes[] = {128, 256, 512, 1024, 4096, 5120, 8192};
392	    int failed = 0;
393	    uint32_t checksum = 0;
394	    for (size_t i = 0; i < sizeof(sizes) / sizeof(sizes[0]); ++i) {
395	        failed += test_size(sizes[i], 50, &checksum);
396	    }
397	    failed += test_repack_gemv();
398	    printf("%s (dispatcher checksum 0x%08x - comparable between runs taking the same dispatcher path)\n",
399	           failed ? "FAILED" : "ALL PASS", checksum);
400	    return failed ? 1 : 0;
401	}
