// ---- F5: software prefetch of the upcoming brick --------------------------
// The gemv streams bricks sequentially (sizeof(block_q1_0_64x1) = 1152 B = 18
// cache lines each). The HW prefetcher on this core is shallow
// (L3C_PFP_LINE_NUM=0, D$ 4 entries), so it cannot run far enough ahead to hide
// the L3/DRAM miss latency that makes this kernel load-bound. Pull the brick
// `dist` blocks ahead into cache explicitly.
//
// Pure hint: results are unchanged (gated by test_prefetch_is_pure). Needs
// zicbop in -march, else GCC drops __builtin_prefetch silently and the
// optimization vanishes with no error - gated by `make check-pf`.
//
// dist is a compile-time constant in every caller, so the whole helper folds
// away at dist=0 and the guard folds to a single compare otherwise. Default 1
// (measured best on ax46mpv_fpga_l3 in-model: 2.14M -> 1.39M cyc on the K=51
// V-proj node, 1.54x; distances 2/4 were worse - one brick ahead already hides
// the latency, more lookahead only adds cache/MSHR pressure).
static inline void q1_prefetch_brick(const block_q1_0_64x1 * bx, int ib, int nb, int dist) {
    if (dist == 0) {
        return;
    }
    const int t = ib + dist;
    if (t < nb) {
        const char * p = (const char *) &bx[t];
        for (size_t o = 0; o < sizeof(block_q1_0_64x1); o += 64) {
            __builtin_prefetch(p + o, 0, 3);
        }
    }
}

